use clap :: { ArgAction , Parser , Subcommand } ; use std :: path :: PathBuf ; use super :: * ; use crate :: global_dep_graph :: PartitioningAlgorithm ; use std :: str :: FromStr ; # [doc = " Subcommands for global dependency graph operations"] # [derive (Subcommand , Debug)] pub enum GlobalGraphCommands { # [doc = " Build the global dependency graph from workspace"] Build { # [doc = " Path to workspace root directory"] workspace_path : PathBuf , # [doc = " Include dev dependencies in the graph"] # [arg (long , action = ArgAction :: SetTrue)] include_dev : bool , # [doc = " Include build dependencies in the graph"] # [arg (long , action = ArgAction :: SetTrue)] include_build : bool , # [doc = " Expand all feature dependencies"] # [arg (long , action = ArgAction :: SetTrue)] expand_features : bool , # [doc = " Output directory for graph files"] # [arg (long , default_value = "./analysis/global_graph")] output_dir : PathBuf , } , # [doc = " Analyze the global dependency graph for Solana patterns"] Analyze { # [doc = " Path to the JSON graph file"] input_path : PathBuf , # [doc = " Output directory for analysis results"] # [arg (long , default_value = "./analysis/global_graph")] output_dir : PathBuf , } , # [doc = " Generate visualization of the dependency graph"] Visualize { # [doc = " Path to the JSON graph file"] input_path : PathBuf , # [doc = " Output path for visualization file"] # [arg (long , default_value = "./analysis/global_graph/graph.dot")] output_path : PathBuf , } , # [doc = " Generate TOML structure analysis and visualization"] TomlStructure { # [doc = " Path to the JSON graph file"] input_path : PathBuf , # [doc = " Output directory for TOML structure analysis"] # [arg (long , default_value = "./analysis/toml_structure")] output_dir : PathBuf , } , # [doc = " Perform graph partitioning using KaMinPar"] Partition { # [doc = " Path to the JSON graph file"] input_path : PathBuf , # [doc = " Number of partitions to create"] # [arg (long , default_value = "8")] partition_count : usize , # [doc = " Balance factor for partitioning (0.0-1.0)"] # [arg (long , default_value = "0.03")] balance_factor : f64 , # [doc = " Partitioning algorithm to use"] # [arg (long , default_value = "kaminpar")] algorithm : String , # [doc = " Output directory for partition results"] # [arg (long , default_value = "./analysis/partitions")] output_dir : PathBuf , } , }